class Solution {public int solve(int[] values,int k){HashMap<Integer,Integer> counts=new HashMap<>();int left=0,best=values.length+1;for(int right=0;right<values.length;right++){counts.put(values[right],counts.getOrDefault(values[right],0)+1);while(counts.size()>=k){best=Math.min(best,right-left+1);int old=values[left++],next=counts.get(old)-1;if(next==0)counts.remove(old);else counts.put(old,next);}}return best>values.length?0:best;}}